window.RTLBenchLSData.register("assets/d3971ef664ea5cede93c1263530b4226946bef8363eb1eafe9133653bb07dc13.txt","module origen_098838 #(\n    parameter CLK_FREQUENCY = 100_000_000,\n    parameter FREQ_PWM = 10_000,\n    parameter CUENTA_INICIAL = 0,\n    parameter CUENTA_MAXIMA = CLK_FREQUENCY/(2*FREQ_PWM),\n    parameter DEBUG = 0\n)(\n    input wire clk,\n    input wire [31:0] entrada,\n    input wire enable,\n    input wire en_log,\n    output reg salida_PWM\n);\n\n    reg [31:0] contador;\n    reg [31:0] registro_comparacion;\n    reg up_down;\n\n    always @(posedge clk) begin\n        if (contador == CUENTA_MAXIMA - 1) begin\n            up_down <= 1;\n            contador <= contador - 1;\n        end else if (contador == 0) begin\n            up_down <= 0;\n            contador <= contador + 1;\n            registro_comparacion <= entrada + CUENTA_MAXIMA/2;\n        end else begin\n            contador <= up_down ? contador - 1 : contador + 1;\n        end\n\n        salida_PWM <= (registro_comparacion > contador);\n    end\n\n    generate\n        if (DEBUG == 1) begin : debug_instance\n            analizador_PWM #(\n                .CLK_FREQUENCY(CLK_FREQUENCY),\n                .FREQ_PWM(FREQ_PWM),\n                .CUENTA_INICIAL(CUENTA_INICIAL),\n                .CUENTA_MAXIMA(CUENTA_MAXIMA)\n            ) analizador_PWM_inst (\n                .clk(clk),\n                .entrada(entrada),\n                .enable(enable),\n                .en_log(en_log),\n                .salida_PWM(salida_PWM),\n                .contador(contador),\n                .registro_comparacion(registro_comparacion),\n                .up_down(up_down)\n            );\n        end\n    endgenerate\n\nendmodule");
